      notMatch: new RegExp("^\\s*(?:\\/\\/|\\*|\\/\\*)|\\b(?:log(?:ger)?|console|winston|pino|metric|analytics|track|audit)\\b|[Rr]ate[_-]?[Ll]imit|[Tt]hrottle|[Ww]hitelist|[Aa]llowlist|\\b(?:jwt\\.verify|verifyToken|verifyJwt|authenticate|passport|req\\.session|req\\.user|req\\.isAuthenticated|bcrypt|csrf)\\b|\\.listen\\(|\\.bind\\(|\\?\\s*['\"`0-9]"),
